import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str):
        self.key = key
        self.expected = expected
        super().__init__(f"Invalid config: {key} = {expected} (expected: {expected})")


def _coerce(value: str, expected: Any) -> Any:
    if isinstance(expected, str):
        return value
    if isinstance(expected, bool):
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(value, "bool")
    if isinstance(expected, int):
        try:
            return int(value)
        except ValueError:
            raise ConfigError(value, "int")
    if isinstance(expected, float):
        try:
            return float(value)
        except ValueError:
            raise ConfigError(value, "float")
    raise ConfigError(value, type(expected).__name__)


def load_config(
    defaults: dict[str, Any],
    toml_path: str | None = None,
    prefix: str = "APP",
    env: dict[str, str] | None = None
) -> dict[str, Any]:
    config = dict(defaults)
    if toml_path and os.path.isfile(toml_path):
        with open(toml_path, "rb") as f:
            toml = tomllib.load(f)
            for key, val in toml.items():
                config[key] = val
    if env is None:
        env = dict(os.environ)
    for key, val in env.items():
        if not key.startswith(prefix + "__"):
            continue
        rest = key[len(prefix) + 2:]
        parts = rest.split("__")
        target = parts[0]
        for p in parts[1:]:
            target = f"{target}__{p}"
        if target not in config:
            raise ConfigError(val, "missing default")
        config[target] = _coerce(val, config[target])
    return config
